import {nivel} from './level.mjs';
import {protocolFloors,scopeProtocolCatalog,scopedProtocolRows,sharedProtocol} from './protocol-scope.mjs';
import {loadProtocolCatalog} from './protocol-catalog.mjs';
import {decodeAgingIndex,analyzeCritical,chileToday,isoDay,validDateRange,ageBands} from './protocol-aging.mjs';
import {matrixFacets,matrixPage} from './protocol-model.mjs';
import {workChart} from './work-charts.mjs';
let pending,resumeCritical;document.addEventListener('visibilitychange',()=>{if(!document.hidden)resumeCritical?.();});const KEY='atlas-protocol-critical-view-v1';
async function loadIndex(catalog){if(pending?.sha===catalog.source.sha256)return pending.promise;const promise=(async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch('protocols/'+catalog.aging.file,{signal:controller.signal});if(!response.ok)throw Error('No se pudo cargar el índice de abiertos. Reintenta o guarda la matriz offline.');return decodeAgingIndex(await response.json(),catalog);}finally{clearTimeout(timer);}})().catch(()=>{if(pending?.promise===promise)pending=null;throw Error('No se pudo leer el índice de abiertos. Comprueba la conexión o completa la copia offline.');});pending={sha:catalog.source.sha256,promise};return promise;}
export async function renderProtocolCritical(root,ctx){
 const esc=ctx.esc,num=n=>Number(n).toLocaleString('es-CL'),date=day=>day?.split('-').reverse().join('-')||'Sin fecha';
 root.innerHTML='<p role="status">Preparando análisis de protocolos abiertos…</p>';
 let catalog,rows;
 try{catalog=await loadProtocolCatalog();rows=scopedProtocolRows(await loadIndex(catalog),nivel.id);}catch(error){if(!root.isConnected)return;root.innerHTML=`<p role="alert">${esc(error.message)}</p><button id="retryCriticalProtocols">Reintentar análisis</button>`;root.querySelector('button').onclick=()=>renderProtocolCritical(root,ctx);return;}
 if(!root.isConnected)return;
 const floor=protocolFloors[nivel.id],key=KEY+':'+nivel.id,scope=scopeProtocolCatalog(catalog,nivel.id,'ABIERTO');
 const filters={asOf:chileToday(),specialty:'',level:'',receiver:'',query:'',dateFrom:'',dateTo:''};let page=0,band='',useToday=true;
 try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved?.sourceSha256===catalog.source.sha256){for(const key of Object.keys(filters))if(typeof saved.filters?.[key]==='string')filters[key]=saved.filters[key].slice(0,300);useToday=saved.asOfMode!=='custom';if(useToday||!isoDay(filters.asOf)){filters.asOf=chileToday();useToday=true;}}}catch{}
 const options=field=>matrixFacets(rows,field).map(([value,n])=>`<option value="${esc(value||'~')}">${esc(value||'Sin dato documentado')} · ${num(n)}</option>`).join('');
 root.innerHTML=`<section class="criticalIntro"><div><span class="section-label">ANTIGÜEDAD DE PROTOCOLOS</span><h2>Protocolos críticos · ${esc(floor.code)}</h2><p>${esc(floor.name)} · Incluye referencias compartidas explícitas al piso.</p><p>Abiertos que han superado un año calendario desde su elaboración, sin fecha de cierre.</p><small>Estados de la matriz al ${date(catalog.source.cutoff)}; antigüedad según la fecha de evaluación.</small></div></section><div class="criticalActions"><label>Evaluar antigüedad al<input id="criticalAsOf" type="date" required></label><button id="criticalToday">Hoy</button></div><details class="criticalMore" ${filters.specialty||filters.level||filters.receiver||filters.dateFrom||filters.dateTo||filters.query?'open':''}><summary>Filtrar por especialidad, nivel, persona o fechas</summary><div class="criticalFilters"><label>Especialidad<select id="criticalSpecialty"><option value="">Todas las especialidades</option>${scope.specialties.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>Nivel del Excel<select id="criticalLevel"><option value="">Todas las referencias de ${esc(floor.code)}</option>${options('level')}</select></label><label>Recibe<select id="criticalReceiver"><option value="">Todas las personas</option>${options('receiver')}</select></label><label>Elaborados desde<input id="criticalDateFrom" type="date"></label><label>Elaborados hasta<input id="criticalDateTo" type="date"></label><label class="criticalQuery">Buscar protocolo<input id="criticalQuery" type="search" placeholder="Nombre o código del proceso…"></label><button id="clearCriticalFilters">Limpiar filtros</button></div></details><p id="criticalScope" class="chartSubtitle"></p><p id="criticalError" role="alert" hidden></p><div id="criticalSummary" class="criticalSummary"></div><div id="criticalCharts" class="chartGrid"></div><section class="criticalList"><div class="matrixResultHead"><h3 id="criticalListTitle">Registros críticos</h3><button id="clearCriticalBand" hidden>Ver todas las antigüedades</button></div><p id="criticalCount" role="status"></p><div class="matrixTableWrap"><table class="matrixTable"><thead><tr><th>Protocolo / folio</th><th>Elaboración</th><th>Nivel</th><th class="matrixWide">Recibe</th><th>Antigüedad</th></tr></thead><tbody id="criticalRows"></tbody></table></div><div class="matrixPagination"><button id="criticalPrevious">Anterior</button><span id="criticalPage"></span><button id="criticalNext">Siguiente</button></div></section>`;
 const $=id=>root.querySelector('#'+id),map={criticalAsOf:'asOf',criticalSpecialty:'specialty',criticalLevel:'level',criticalReceiver:'receiver',criticalDateFrom:'dateFrom',criticalDateTo:'dateTo',criticalQuery:'query'};
 for(const [id,key] of Object.entries(map)){$(id).value=filters[key];if($(id).tagName==='SELECT'&&$(id).value!==filters[key])filters[key]='';$(id)[id==='criticalQuery'?'oninput':'onchange']=event=>{filters[key]=event.target.value;if(id==='criticalAsOf')useToday=false;page=0;band='';render();};}
 const save=()=>{try{localStorage.setItem(key,JSON.stringify({sourceSha256:catalog.source.sha256,asOfMode:useToday?'today':'custom',filters}));}catch{}};
 function choose(typeId,recordId=null){ctx.choose({typeId,recordId,filters:{criticalOnly:true,asOf:filters.asOf,state:'ABIERTO',level:filters.level,receiver:filters.receiver,dateField:'issued',dateFrom:filters.dateFrom,dateTo:filters.dateTo}});}
 function render(){
  if(useToday){filters.asOf=chileToday();$('criticalAsOf').value=filters.asOf;}const report=analyzeCritical(rows,catalog,filters),invalid=!report.valid;$('criticalScope').textContent=(catalog.specialties.find(item=>item.id===filters.specialty)?.name||'Todas las especialidades')+' · '+(filters.level==='~'?'Sin nivel documentado':filters.level?'Nivel '+filters.level:floor.name+' · '+floor.code);
  $('criticalError').hidden=!invalid;$('criticalError').textContent=!isoDay(filters.asOf)?'Selecciona una fecha válida para evaluar la antigüedad.':!validDateRange(filters.dateFrom,filters.dateTo)?'La fecha inicial debe ser anterior o igual a la fecha final.':'';
  $('criticalSummary').innerHTML=[['criticalTotal','Críticos · más de un año',report.critical.length],['criticalOpen','Abiertos en la consulta',report.open],['criticalMissing','Sin elaboración válida',report.missing]].map(([id,label,n])=>`<article><span>${label}</span><b id="${id}">${num(n)}</b></article>`).join('');
  $('criticalCharts').innerHTML=invalid?'':!report.critical.length?'<section class="chartCard"><p>No hay protocolos críticos con esta fecha y estos filtros.</p></section>':`<section class="chartCard"><div class="chartHeading"><h3>Procesos con más protocolos críticos</h3><span>10 primeros de ${report.types.length}</span></div><p class="chartSubtitle">${num(report.critical.length)} críticos en total. Selecciona un proceso para consultar sus registros.</p><div class="workChartRows">${report.types.slice(0,10).map(({type,n})=>`<button type="button" class="workChartRow criticalTypeBar" data-critical-type="${type.id}"><span><b>${esc(type.code)}</b><small>${esc(type.name)}</small></span><b>${num(n)}</b><em class="workBar"><span style="width:${n/report.types[0].n*100}%;background:#ad544d"></span></em></button>`).join('')}</div></section>${workChart({title:'Críticos por antigüedad',kind:'pie',filter:'critical-age',items:report.bands.map(item=>({key:item.name,n:item.n,color:item.color})),subtitle:'Cada registro aparece en un solo tramo. Selecciona un tramo para filtrar el listado.'},esc)}`;
  root.querySelectorAll('[data-critical-type]').forEach(button=>button.onclick=()=>choose(button.dataset.criticalType));root.querySelectorAll('[data-work-filter="critical-age"]').forEach(button=>{const apply=()=>{band=report.bands.find(item=>item.name===button.dataset.workState)?.key||'';page=0;renderList(report);};button.onclick=apply;if(button.tagName!=='BUTTON')button.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();apply();}};});renderList(report);save();
 }
 function renderList(report){root.querySelectorAll('[data-work-filter="critical-age"]').forEach(node=>node.setAttribute('aria-pressed',String(!!band&&node.dataset.workState===ageBands.find(item=>item.key===band)?.name)));const shown=band?report.critical.filter(row=>row.age.band===band):report.critical,current=matrixPage(shown,page);page=current.page;$('criticalCount').textContent=num(shown.length)+' registros críticos · evaluación al '+date(filters.asOf);$('criticalListTitle').textContent=band?'Registros · '+ageBands.find(item=>item.key===band).name:'Registros críticos';$('clearCriticalBand').hidden=!band;
  const types=new Map(catalog.types.map(type=>[type.id,type]));$('criticalRows').innerHTML=current.rows.map(row=>`<tr data-critical-row="${esc(row.id)}"><td><button data-critical-record="${esc(row.id)}">${esc(types.get(row.typeId).code)} · ${esc(row.folio||'Sin folio')}</button><small>${esc(types.get(row.typeId).name)}</small></td><td>${date(row.age.issued)}</td><td>${esc(row.level||'Sin nivel')}${sharedProtocol(row.level)?'<small>Compartido</small>':''}</td><td class="matrixWide">${esc(row.receiver||'Sin receptor')}</td><td><span class="criticalBadge">${num(row.age.days)} días</span></td></tr>`).join('')||'<tr><td colspan="5">Sin registros críticos en esta consulta.</td></tr>';$('criticalPage').textContent='Página '+(page+1)+' de '+current.pages;$('criticalPrevious').disabled=page===0;$('criticalNext').disabled=page+1>=current.pages;
  root.querySelectorAll('[data-critical-record]').forEach(button=>button.onclick=()=>{const row=shown.find(row=>row.id===button.dataset.criticalRecord);choose(row.typeId,row.id);});$('criticalPrevious').onclick=()=>{page--;renderList(report);};$('criticalNext').onclick=()=>{page++;renderList(report);};$('clearCriticalBand').onclick=()=>{band='';page=0;renderList(report);};
 }
 $('criticalToday').onclick=()=>{useToday=true;filters.asOf=chileToday();$('criticalAsOf').value=filters.asOf;page=0;band='';render();};resumeCritical=()=>{if(!root.isConnected){resumeCritical=null;return;}if(useToday)render();};
 $('clearCriticalFilters').onclick=()=>{useToday=true;Object.assign(filters,{asOf:chileToday(),specialty:'',level:'',receiver:'',query:'',dateFrom:'',dateTo:''});for(const [id,key] of Object.entries(map))$(id).value=filters[key];page=0;band='';render();};render();
}
